mapper.select:
SELECT r.id, r.user_id, u.username, u.real_name, r.equipment_id, e.name AS equipmentName, e.code AS equipmentCode, e.image AS equipmentImage, r.lab_id, l.name AS labName, r.date, r.end_date, r.start_time, r.end_time, r.purpose, r.status, r.approve_comment, r.return_note, r.returned_at, r.create_time FROM reservation r LEFT JOIN `user` u ON r.user_id = u.id LEFT JOIN equipment e ON r.equipment_id = e.id LEFT JOIN lab l ON r.lab_id = l.id
AND r.user_id = #{userId}
AND r.status = #{status}
AND (e.name LIKE CONCAT('%', #{keyword}, '%') OR e.code LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
AND r.date >= #{dateFrom}
AND r.date <= #{dateTo}
ORDER BY r.date DESC, r.start_time DESC, r.id DESC

SELECT COUNT(*)
FROM reservation
WHERE equipment_id = #{equipmentId}
  AND status IN ('PENDING', 'APPROVED')
  AND CONCAT(IFNULL(end_date, date), ' ', end_time) > #{start}
  AND CONCAT(date, ' ', start_time) < #{end}
